/**
 * Guide-mode contract.
 *
 * The panel keeps **one** `FileCity3D` instance (owned by `GuideStage`) and
 * never unmounts it. A *mode* (idle / tour / commit / …) is not a layout that
 * contains the map — it's a controller + overlay that:
 *   1. pushes the map's framing (`MapState`) to the stage via `useMapController`,
 *   2. renders its own chrome (header / panels / footer) over the freed margins.
 *
 * Because the map is a singleton and chrome overlays it absolutely, switching
 * modes only animates the shared scene (a `safeArea` reframe) and swaps chrome
 * — it never rebuilds the 3D scene.
 */

import type { FC } from 'react';
import type {
  CityData,
  CityBuilding,
  CitySource,
  HighlightLayer,
  IsolationMode,
} from '@principal-ai/file-city-react';
import type { PanelEventEmitter } from '@principal-ade/panel-framework-core';
import type {
  FileCityGuidePanelActions,
  FileCityGuidePanelContext,
} from '../../../types/FileCityGuidePanel';

/**
 * Fractional canvas insets the flat city frames itself into — re-declared
 * locally because `@principal-ai/file-city-react` doesn't export the type.
 * Structurally identical to the renderer's `SafeArea`, so it flows straight
 * into `FileCity3D`'s `safeArea` prop. Each value is a fraction in [0, 1).
 */
export interface SafeArea {
  top?: number;
  bottom?: number;
  left?: number;
  right?: number;
}

/**
 * Everything a mode needs to render, supplied by the stage. Modes read theme
 * via `useTheme()` themselves, so it isn't carried here.
 */
export interface GuideEnv {
  /** The built city — the corpus every mode frames/filters. Null while loading. */
  cityData: CityData | null;
  /**
   * Host-provided multi-repo cities, each with its own city data, world
   * position, and label. When present (length > 0), `FileCity3D` renders
   * every source side-by-side and `cityData` is ignored. Forward-only: a
   * mode never derives repo roots from paths — it attaches its layers to
   * every source whose buildings contain the path (building membership,
   * not prefix), so the same repo appearing in two version-cities lights
   * up in both.
   */
  citySources?: CitySource[];
  /** Panel event bus — modes emit `file:open` etc. through it. */
  events: PanelEventEmitter;
  /** Host actions (openFile, fetchAudioUrls, …). */
  actions: FileCityGuidePanelActions;
  /** Target time (ms) for the whole 3D grow ripple to finish. */
  growDuration: number;
  /**
   * Host-requested idle focus directory (e.g. a selected package's subtree).
   * A takeover mode that frames the full city — like readme mode — forwards
   * this into its `MapState` so the focus survives the mode instead of the
   * mode's full-city push clearing it. Null when the host isn't focusing.
   */
  focusDirectory?: string | null;
  /**
   * Folder paths (repo-relative, no leading slash) the host wants stripped
   * from every city — the idle city is already pruned by the stage's main
   * memo, but modes that build their own ci
