+import type { Meta, StoryObj } from '@storybook/react';
+import React, { useMemo, useState } from 'react';
+import rawSession from './data/opencode-session-raw-events.json';
+
+type AnyRecord = Record<string, unknown>;
+
+/**
+ * Shape of a raw opencode V1 event exactly as the trail-viewer reads it from
+ * sqlite (event table: id, aggregate_id, seq, type, data). Mirrors
+ * `RawV1Event` in @principal-ai/agent-monitoring (opencode/v1-types.ts), which
+ * is not currently exported from the package entry — define locally until the
+ * package surfaces it.
