  repos: Array<{ owner: string; name: string }>;
  description: string;
  points: string[];
  mermaid: string;
}
```

Then in concepts.ts, `import type { ConceptCardData } ...` and `export type ConceptCard = ConceptCardData; export type ChangeType = ConceptChangeType;`. That keeps the renderer API unchanged (ConceptCard still exported) while sharing the shape.

Wait, but concepts.ts defines `ChangeType` and `ConceptCard` and the curated `CONCEPT_CARDS` array. I can just re-export/alias. Let me do:

```ts
import type { ConceptCardData, ConceptChangeType } from "../../shared/contract";
export type ChangeType = ConceptChangeType;
export type ConceptCard = ConceptCardData;
